def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for _, o in opponents_status.items():
        if o.get('alive', False):
            alive_opponents.append(o)

    if not alive_opponents:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Immediate reaction to yesterday's bids (only previous_trace)
    prev_bids = []
    for o in alive_opponents:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Supply pressure: lower supply means fewer winners need to fight harder.
    # Use a simple scaling without relying on unknown game mechanics.
    supply_mid = (MIN_SUPPLY + MAX_SUPPLY) / 2.0
    tightness = 1.0
    if supply >= supply_mid:
        tightness = 0.85
    else:
        tightness = 1.15

    # Base bid policy: aim to secure water while conserving budget.
    # If my HP is low or no_water_days already high, bid more aggressively.
    if hp <= 2.0 or no_water_days >= 2:
        base = DAILY_SALARY * 0.85
    elif hp <= 4.0:
        base = DAILY_SALARY * 0.65
    else:
        base = DAILY_SALARY * 0.52

    # Exploit yesterday's spending: if someone paid very high, they likely value survival.
    # Bid above their yesterday level only when supply is tight and I can afford it.
    if highest_prev_bid >= DAILY_SALARY * 1.35:
        # Eric-like behavior: increase bid but cap by affordability and budget.
        target = max(base, highest_prev_bid * 0.92)
    elif highest_prev_bid >= DAILY_SALARY * 0.85:
        target = max(base, highest_prev_bid * 0.75)
    else:
        target = base

    # Apply tightness and a small day-based adjustment to avoid ties.
    # (Simultaneous bids; slight oscillation can help.)
    target *= tightness
    if day % 2 == 1:
        target *= 1.03

    # Ensure we never bid negative or above budget.
    bid = max(0.0, min(budget, target))

    # Additional safety: if budget is very low, bid a smaller fraction.
    if budget < DAILY_SALARY * 0.6:
        bid = min(bid, budget * 0.9)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 90
    WATER_REQ = 9

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    opp_pressure = 0.0
    for opp in opponents_status.values():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = prev['bid']
                prev_bids.append(bid)
                if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                    opp_pressure = max(opp_pressure, bid + 8.0)
                else:
                    opp_pressure = max(opp_pressure, bid)

    if not alive_opponents:
        if hp <= 2 or no_water_days >= 1:
            return min(budget, DAILY_SALARY * 0.7)
        return min(budget, DAILY_SALARY * 0.2)

    scarcity = WATER_REQ / max(1.0, supply)
    severe_need = hp <= 2 or no_water_days >= 2
    moderate_need = hp <= 4 or no_water_days >= 1

    if severe_need:
        base = DAILY_SALARY * (1.05 if supply <= 17 else 0.92)
        target = max(base, opp_pressure + 3.0 if prev_bids else base)
        return min(budget, target)

    if moderate_need:
        base = DAILY_SALARY * (0.82 if supply <= 17 else 0.68)
        if prev_bids:
            highest_prev = max(prev_bids)
            if highest_prev >= 110:
                target = max(base, highest_prev * 0.92)
            else:
                target = max(base, highest_prev + 2.0)
        else:
            target = base
        return min(budget, target)

    if prev_bids:
        highest_prev = max(prev_bids)
        if highest_prev >= 120:
            target = DAILY_SALARY * 0.28
        elif highest_prev >= 100:
            target = DAILY_SALARY * 0.38
        elif highest_prev >= 75:
            target = highest_prev * 0.78
        else:
            target = max(DAILY_SALARY * 0.42, highest_prev + 1.0)
    else:
        target = DAILY_SALARY * 0.4

    if supply <= 16:
        target += 8.0
    elif supply >= 23:
        target -= 6.0

    if day >= 8 and hp >= 7 and no_water_days == 0:
        target *= 0.9

    target = max(0.0, target * (0.92 + 0.25 * scarcity))
    return min(budget, target)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    default_avg_bid = 75.0
    default_max_bid = 100.0

    avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else default_avg_bid
    max_prev_bid = max(yesterday_bids) if yesterday_bids else default_max_bid

    bid = 0.0

    if my_status['hp'] <= 2 or my_status['no_water_days'] > 0:
        bid = DAILY_SALARY * 0.95
        if max_prev_bid > DAILY_SALARY * 0.8:
            bid = max(bid, max_prev_bid + 5.0)
    elif my_status['hp'] <= 5:
        bid = DAILY_SALARY * 0.75
        if max_prev_bid > DAILY_SALARY * 0.6:
            bid = max(bid, avg_prev_bid * 1.1)
        else:
            bid = max(bid, DAILY_SALARY * 0.65)
    else:
        total_competitor_water_req = WATER_REQ + sum(o['water_requirement'] for o in alive_opponents)

        if day_context['supply'] >= total_competitor_water_req * 1.5:
            bid = DAILY_SALARY * 0.4
            bid = min(bid, avg_prev_bid * 0.9)
        elif day_context['supply'] < total_competitor_water_req * 1.1:
            bid = DAILY_SALARY * 0.6
            bid = max(bid, avg_prev_bid * 1.05)
        else:
            bid = DAILY_SALARY * 0.5
            bid = max(bid, avg_prev_bid)

    final_bid = min(bid, my_status['budget'])
    final_bid = max(final_bid, DAILY_SALARY * 0.05)

    return final_bid
